const listMessages = `-- name: ListMessages :many
SELECT m.pos, m.body
FROM uma_messages m
WHERE m.tenant_id = $1 AND m.pos > $2
  AND (cardinality($3::text[]) = 0 OR m.inbox_id = ANY (($3::text[])::uuid[]))
  AND ($4::uuid IS NULL
       OR (m.inbox_id = $4::uuid AND m.conversation_id = $5::uuid))
  AND ($6::uuid IS NULL
       OR (m.task_id = $6::uuid
           AND m.inbox_id = $7::uuid AND m.conversation_id = $8::uuid))
  AND (cardinality($9::uuid[]) = 0 OR EXISTS (
    SELECT 1 FROM uma_conversation_labels l
    WHERE l.tenant_id = m.tenant_id AND l.conversation_id = m.conversation_id AND l.label_id = ANY ($9::uuid[])
  ))
  AND (cardinality($10::uuid[]) = 0 OR cardinality($10::uuid[]) = (
    SELECT count(*) FROM uma_conversation_labels l
    WHERE l.tenant_id = m.tenant_id AND l.conversation_id = m.conversation_id AND l.label_id = ANY ($10::uuid[])
  ))
  AND NOT EXISTS (
    SELECT 1 FROM uma_conversation_labels l
    WHERE l.tenant_id = m.tenant_id AND l.conversation_id = m.conversation_id AND l.label_id = ANY ($11::uuid[])
  )
  AND (cardinality($12::text[]) = 0 OR m.search_tokens @> $12::text[])
  AND ($13::bigint IS NULL
       OR (m.occurred_unix, m.occurred_nanos) >= ($13::bigint, $14::integer))
  AND ($15::bigint IS NULL
       OR (m.occurred_unix, m.occurred_nanos) < ($15::bigint, $16::integer))
  AND ($17::boolean IS NULL
       OR $17::boolean = EXISTS (
           SELECT 1 FROM uma_message_attachments a WHERE a.tenant_id = m.tenant_id AND a.message_id = m.id))
  AND (cardinality($18::text[]) + cardinality($19::text[]) = 0
       OR EXISTS (
           SELECT 1
           FROM uma_message_attachments a
           JOIN uma_attachments r
             ON r.tenant_id = a.tenant_id AND r.inbox_id = a.inbox_id::uuid AND r.id = a.attachment_id::uuid
           CROSS JOIN LATERAL (
               SELECT translate(btrim(split_part(r.body -> 'attachment' -> 'metadata' ->> 'media_type', ';', 1), E' \t'),
                   'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') AS media_type
           ) n
           WHERE a.tenant_id = m.tenant_id AND a.message_id = m.id
             AND r.body ->> 'state' IS DISTINCT FROM 'redacted'
             AND n.media_type <> ''
             AND (n.media_type = ANY ($18::text[])
                  OR EXISTS (SELECT 1 FROM unnest($19::text[]) AS p(typ) WHERE starts_with(n.media_type, p.typ || '/')))))
ORDER BY m.pos
LIMIT $20
`

