const resolveDestination = `-- name: ResolveDestination :many
SELECT body
FROM uma_inboxes
WHERE tenant_id = $1 AND channel_id = $2 AND $3::text = ANY (destinations)
ORDER BY pos
LIMIT 2
`

type ResolveDestinationParams struct {
	TenantID    string
	ChannelID   string
	Destination string
}

func (q *Queries) ResolveDestination(ctx context.Context, arg ResolveDestinationParams) ([][]byte, error) {
	rows, err := q.db.Query(ctx, resolveDestination, arg.TenantID, arg.ChannelID, arg.Destination)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items [][]byte
	for rows.Next() {
		var body []byte
		if err := rows.Scan(&body); err != nil {
			return nil, err
		}
		items = append(items, body)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

